import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { cleanText, hasMention } from './nettoyer-mentions.mjs';

// Le nom de l'outil est assemblé ici pour que ce fichier n'en contienne aucune mention.
const TOOL = ['Cl', 'aude'].join('');
const SITE = `${TOOL.toLowerCase()}.ai`;
const COMPANY = ['anthr', 'opic'].join('');

describe('nettoyer-mentions : pieds de page', () => {
  it('retire le pied « Generated by » et le séparateur qui le précède', () => {
    const text = `Corps de l'issue.\n\n---\n_Generated by [${TOOL} Code](https://${SITE}/code)_`;
    assert.equal(cleanText(text), "Corps de l'issue.");
  });

  it('retire la variante avec lien de session', () => {
    const text = `Texte\n\n---\n_Generated by [${TOOL} Code](https://${SITE}/code/session_01AbC)_\n`;
    assert.equal(cleanText(text), 'Texte');
  });

  it('retire « 🤖 Generated with » et un lien de session seul sur sa ligne', () => {
    const text = [
      '## Résumé',
      '- point',
      '',
      `🤖 Generated with [${TOOL} Code](https://${TOOL.toLowerCase()}.com/${TOOL.toLowerCase()}-code)`,
      '',
      `https://${SITE}/code/session_01XyZ`,
    ].join('\n');
    assert.equal(cleanText(text), '## Résumé\n- point');
  });

  it('retire une ligne d’attribution recopiée', () => {
    const text = `Message\n\nCo-authored-by: ${TOOL} <noreply@${COMPANY}.com>`;
    assert.equal(cleanText(text), 'Message');
  });

  it('neutralise une mention dans une phrase', () => {
    const text = `La fusion porte encore \`Co-authored-by: ${TOOL}\`, contraire à CLAUDE.md.`;
    assert.equal(cleanText(text), 'La fusion porte encore `Co-authored-by`, contraire à CLAUDE.md.');
  });
});

describe('nettoyer-mentions : textes inchangés', () => {
  it('laisse intact un texte sans pied, à l’octet près', () => {
    for (const text of ['Texte\n', 'Liste :\n\n---\nsuite', 'Modifie `CLAUDE.md`.  \n', '']) {
      assert.equal(cleanText(text), text);
    }
  });

  it('accepte un corps absent', () => {
    assert.equal(cleanText(null), null);
    assert.equal(cleanText(undefined), undefined);
  });
});

describe('nettoyer-mentions : détection', () => {
  it('voit une mention mais pas le nom du fichier CLAUDE.md', () => {
    assert.equal(hasMention(`par ${TOOL}`), true);
    assert.equal(hasMention(`noreply@${COMPANY}.com`), true);
    assert.equal(hasMention('règle de CLAUDE.md'), false);
    assert.equal(hasMention(null), false);
  });
});
